UPDATE "BOARD_IMG" SET
	BOARD_NO = #{boardNo}
WHERE BOARD_IMG_RENAME IN 

	#{name}

		UPDATE "BOARD" SET
		BOARD_DEL_FL = 'Y'
		WHERE BOARD_NO = #{boardNo}

		AND CATEGORY_CODE = #{categoryCode}

		AND (
        MEMBER_NO = #{memberNo}
        OR 
        #{authorLevel} = 2
    )

		UPDATE "BOARD" SET
		BOARD_TITLE = #{boardTitle},
		BOARD_CONTENT = #{boardContent}
		WHERE BOARD_NO = #{boardNo}

		AND CATEGORY_CODE = #{categoryCode}

		AND (
        MEMBER_NO = #{memberNo}
        OR 
        #{authorLevel} = 2
        )
